  "Find your perfect stay": { ar: "اعثر على إقامتك المثالية", es: "Encuentra tu alojamiento ideal", fr: "Trouvez votre séjour idéal", it: "Trova il soggiorno perfetto", zh: "寻找理想住宿", de: "Finde deine perfekte Unterkunft", pl: "Znajdź idealny nocleg", cs: "Najděte perfektní ubytování" },
