  "What are you planning?": { ar: "ماذا تخطط؟", es: "¿Qué estás planeando?", fr: "Que préparez-vous ?", it: "Cosa stai pianificando?", zh: "你在计划什么？", de: "Was planst du?", pl: "Co planujesz?", cs: "Co plánujete?" },
